import { useEffect, useMemo, useState } from 'react'
import { Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, Bell, Building2, Check, ChevronDown, CircleHelp, ClipboardCheck, Clock3, FileSpreadsheet, FileText, KeyRound, LayoutDashboard, LogOut, Menu, PlugZap, Settings, ShieldCheck, Users, X, type LucideIcon } from 'lucide-react'
import type { AppData, AuditEntry, Company, Group, ModuleKey, Regime, TaxFiling } from './domain/types'
import { DATA_SOURCE_LABEL } from './data/emptyData'
import { repository } from './data/repository'
import { formatCnpj, formatDate, initials, makeId, normalizeCnpj } from './domain/format'
import { validateCompany } from './domain/validation'
import { exportCompanies, parseCompanies } from './services/importExport'
import { Button, DataTable, type Column, EmptyState, FilterSelect, FilePicker, Modal, PageTitle, SearchBox, StatusBadge, Toast } from './components/ui'
import machadoLogo from '../assets/branding/machado-contabilidade-original.png'

type NavItem = { key: ModuleKey; label: string; icon: LucideIcon; group: string }
const nav: NavItem[] = [
  { key: 'dashboard', label: 'Visão geral', icon: LayoutDashboard, group: 'INÍCIO' },
  { key: 'empresas', label: 'Empresas', icon: Building2, group: 'CARTEIRA' },
  { key: 'simples', label: 'Simples Nacional', icon: FileText, group: 'CARTEIRA' },
  { key: 'real', label: 'Lucro Real', icon: FileText, group: 'CARTEIRA' },
  { key: 'presumido', label: 'Lucro Presumido', icon: FileText, group: 'CARTEIRA' },
  { key: 'certificados', label: 'Certificados', icon: KeyRound, group: 'OPERAÇÃO' },
  { key: 'integracoes', label: 'Integrações', icon: PlugZap, group: 'OPERAÇÃO' },
  { key: 'pendencias', label: 'Pendências', icon: ClipboardCheck, group: 'OPERAÇÃO' },
  { key: 'grupos', label: 'Grupos', icon: Users, group: 'GESTÃO' },
  { key: 'historico', label: 'Histórico', icon: Activity, group: 'GESTÃO' },
  { key: 'usuarios', label: 'Usuários', icon: ShieldCheck, group: 'GESTÃO' },
  { key: 'configuracoes', label: 'Configurações', icon: Settings, group: 'SISTEMA' },
  { key: 'importacao', label: 'Importar / exportar', icon: FileSpreadsheet, group: 'SISTEMA' },
]
type FormField = { key: string; label: string; type?: string; options?: string[]; required?: boolean; wide?: boolean }
const specs: Partial<Record<ModuleKey, { title: string; singular: string; fields: FormField[] }>> = {
  simples: { title: 'Fechamento Simples Nacional', singular: 'fechamento', fields: [{ key: 'empresa', label: 'Empresa', required: true }, { key: 'periodo', label: 'Competência', type: 'month', required: true }, { key: 'obrigacao', label: 'Rotina / obrigação', required: true }, { key: 'status', label: 'Status', options: ['Não iniciada', 'Em andamento', 'Transmitida'] }, { key: 'responsavel', label: 'Responsável' }, { key: 'prazo', label: 'Prazo', type: 'date' }] },
  real: { title: 'Fechamento Lucro Real', singular: 'fechamento', fields: [{ key: 'empresa', label: 'Empresa', required: true }, { key: 'periodo', label: 'Competência', type: 'month', required: true }, { key: 'obrigacao', label: 'Rotina / obrigação', required: true }, { key: 'status', label: 'Status', options: ['Não iniciada', 'Em andamento', 'Transmitida'] }, { key: 'responsavel', label: 'Responsável' }, { key: 'prazo', label: 'Prazo', type: 'date' }] },
  presumido: { title: 'Fechamento Lucro Presumido', singular: 'fechamento', fields: [{ key: 'empresa', label: 'Empresa', required: true }, { key: 'periodo', label: 'Competência', type: 'month', required: true }, { key: 'obrigacao', label: 'Rotina / obrigação', required: true }, { key: 'status', label: 'Status', options: ['Não iniciada', 'Em andamento', 'Transmitida'] }, { key: 'responsavel', label: 'Responsável' }, { key: 'prazo', label: 'Prazo', type: 'date' }] },
  pendencias: { title: 'Central de pendências', singular: 'pendência', fields: [{ key: 'titulo', label: 'Descrição', required: true, wide: true }, { key: 'empresa', label: 'Empresa' }, { key: 'tipo', label: 'Categoria', options: ['Fiscal', 'Contábil', 'Folha', 'Certificado', 'Integração', 'Outro'] }, { key: 'prioridade', label: 'Prioridade', options: ['Alta', 'Média', 'Baixa'] }, { key: 'prazo', label: 'Prazo', type: 'date' }, { key: 'status', label: 'Status', options: ['Aberta', 'Em andamento', 'Concluída'], required: true } ] },
  certificados: { title: 'Controle de certificados', singular: 'certificado', fields: [{ key: 'empresa', label: 'Empresa', required: true }, { key: 'tipo', label: 'Tipo', options: ['e-CNPJ A1', 'e-CNPJ A3', 'e-CPF', 'Outro'] }, { key: 'validade', label: 'Validade', type: 'date' }, { key: 'responsavel', label: 'Responsável' }, { key: 'status', label: 'Status', options: ['Válido', 'Vence em breve', 'Expirado'], required: true }] },
  integracoes: { title: 'Controle de integrações', singular: 'integração', fields: [{ key: 'nome', label: 'Nome da integração', required: true }, { key: 'fornecedor', label: 'Fornecedor' }, { key: 'status', label: 'Status', options: ['Conectada', 'Atenção', 'Desconectada'], required: true }, { key: 'ultimaSincronia', label: 'Última sincronização', type: 'date' }] },
  grupos: { title: 'Gestão de grupos', singular: 'grupo', fields: [{ key: 'nome', label: 'Nome do grupo', required: true }, { key: 'descricao', label: 'Descrição', wide: true }] },
  usuarios: { title: 'Gestão de usuários', singular: 'usuário', fields: [{ key: 'nome', label: 'Nome completo', required: true }, { key: 'email', label: 'E-mail', type: 'email', required: true }, { key: 'perfil', label: 'Perfil', options: ['Administrador', 'Contador', 'Fiscal', 'Leitura'], required: true }, { key: 'status', label: 'Status', options: ['Ativo', 'Inativo'], required: true }] },
}
const fieldsCompany: FormField[] = [{ key: 'razaoSocial', label: 'Razão social', required: true, wide: true }, { key: 'nomeFantasia', label: 'Nome fantasia' }, { key: 'cnpj', label: 'CNPJ', required: true }, { key: 'regime', label: 'Regime tributário', options: ['Simples Nacional', 'Lucro Real', 'Lucro Presumido'] }, { key: 'status', label: 'Situação', options: ['Ativa', 'Inativa', 'Suspensa', 'Em implantação'] }, { key: 'cidade', label: 'Cidade' }, { key: 'uf', label: 'UF' }, { key: 'responsavel', label: 'Responsável interno' }, { key: 'email', label: 'E-mail', type: 'email' }, { key: 'telefone', label: 'Telefone' }, { key: 'vencimento', label: 'Dia de vencimento', type: 'number' }, { key: 'grupo', label: 'Grupo' }, { key: 'observacoes', label: 'Observações', wide: true }]
const permissionAreas = ['dashboard','empresas','simples','real','presumido','certificados','integracoes','pendencias','grupos','historico','usuarios','configuracoes','importacao']
const permissionLabels: Record<string,string> = { dashboard:'Visão geral', empresas:'Empresas e fichas', simples:'Simples Nacional', real:'Lucro Real', presumido:'Lucro Presumido', certificados:'Certificados', integracoes:'Integrações', pendencias:'Pendências', grupos:'Grupos', historico:'Histórico', usuarios:'Usuários e permissões', configuracoes:'Configurações', importacao:'Importar e exportar' }
const roleDefaults: Record<string,string[]> = { Administrador:permissionAreas, Contador:['dashboard','empresas','simples','real','presumido','certificados','integracoes','pendencias','grupos','historico'], Fiscal:['dashboard','empresas','simples','real','presumido','certificados','pendencias'], Leitura:['dashboard','empresas','simples','real','presumido','certificados','integracoes','pendencias','grupos','historico'] }
const blankData: AppData = { companies: [], pendencies: [], certificates: [], integrations: [], groups: [], audit: [], users: [], taxFilings: [], officialSourceLoaded: true }

export default function App() {
  const [data, setData] = useState<AppData>(blankData)
  const [ready, setReady] = useState(false)
  const [logged, setLogged] = useState(() => sessionStorage.getItem('machado-session') === 'active')
  const [module, setModule] = useState<ModuleKey>('dashboard')
  const [selected, setSelected] = useState<Company | null>(null)
  const [modal, setModal] = useState<{ kind: 'form' | 'view' | 'confirm' | 'import' | 'detail'; module: ModuleKey; record?: Record<string, unknown> } | null>(null)
  const [query, setQuery] = useState('')
  const [filter, setFilter] = useState('')
  const [page, setPage] = useState(1)
  const [sort, setSort] = useState('')
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc')
  const [toast, setToast] = useState('')
  const [toastKind, setToastKind] = useState<'success' | 'error'>('success')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [importPreview, setImportPreview] = useState<{ companies: Company[]; errors: string[] } | null>(null)
  const [importing, setImporting] = useState(false)
  const [settings, setSettings] = useState(() => { const saved = JSON.parse(localStorage.getItem('machado-settings') || '{"notifications":true,"weekStart":"monday","brand":"Machado Contabilidade"}'); if (saved.brand === 'Machado Serviços Contábeis') saved.brand = 'Machado Contabilidade'; return saved })

  useEffect(() => { repository.load().then((loaded) => { setData(loaded); setReady(true) }) }, [])
  useEffect(() => { if (ready) repository.save(data) }, [data, ready])
  useEffect(() => { setPage(1) }, [query, filter, module])
  const announce = (message: string, kind: 'success' | 'error' = 'success') => { setToast(message); setToastKind(kind); window.setTimeout(() => setToast(''), 3600) }
  const audit = (action: string, mod: string, detail: string) => ({ id: makeId(), data: new Date().toISOString(), usuario: 'Operador local', acao: action, modulo: mod, detalhe: detail })
  const setSection = (key: ModuleKey) => { setModule(key); setSelected(null); setQuery(''); setFilter(''); setMobileOpen(false) }
  const openCompanyForm = (company?: Company, regime?: Company['regime']) => setModal({ kind: 'form', module: 'empresas', record: company ? { ...company } : regime ? { regime, status: 'Ativa' } : { status: 'Ativa', regime: 'Simples Nacional' } })
  const openNewForm = (key: ModuleKey) => {
    const defaults: Partial<Record<ModuleKey, Record<string, unknown>>> = { pendencias: { status: 'Aberta', prioridade: 'Média' }, integracoes: { status: 'Desconectada' }, usuarios: { perfil: 'Leitura', status: 'Ativo' } }
    setModal({ kind: 'form', module: key, record: defaults[key] })
  }
  const addItem = (mod: ModuleKey, raw: Record<string, unknown>) => {
    if (mod === 'empresas') {
      const checked = validateCompany(raw)
      if (!checked.success) { announce(Object.values(checked.errors)[0], 'error'); return }
      const duplicate = data.companies.some((c) => normalizeCnpj(c.cnpj) === normalizeCnpj(checked.data.cnpj) && c.id !== raw.id)
      if (duplicate) { announce('Já existe uma empresa cadastrada com este CNPJ.', 'error'); return }
      const id = String(raw.id || makeId()); const now = new Date().toISOString()
      const company = { ...checked.data, unidade: String(raw.unidade || ''), sourceRecords: raw.sourceRecords as Company['sourceRecords'], id, createdAt: String(raw.createdAt || now), updatedAt: now } as Company
      setData((d) => ({ ...d, companies: raw.id ? d.companies.map((x) => x.id === id ? company : x) : [company, ...d.companies], audit: [audit(raw.id ? 'Edição' : 'Cadastro', 'Empresas', company.razaoSocial), ...d.audit] }))
      setSelected((current) => current?.id === id ? company : current)
      announce(raw.id ? 'Cadastro atualizado.' : 'Empresa cadastrada.'); setModal(null); return
    }
    const spec = specs[mod]; if (!spec) return
    const id = String(raw.id || makeId()); const regimeByModule: Partial<Record<ModuleKey, Regime>> = { simples: 'Simples Nacional', real: 'Lucro Real', presumido: 'Lucro Presumido' }; const row = { ...raw, id, ...(regimeByModule[mod] ? { regime: regimeByModule[mod] } : {}) } as never
    const prop = ({ pendencias: 'pendencies', certificados: 'certificates', integracoes: 'integrations', grupos: 'groups', usuarios: 'users', simples: 'taxFilings', real: 'taxFilings', presumido: 'taxFilings' } as const)[mod as 'pendencias'] as keyof AppData
    setData((d) => ({ ...d, [prop]: raw.id ? (d[prop] as Array<{ id: string }>).map((x) => x.id === id ? row : x) : [row, ...d[prop] as never[]], audit: [audit(raw.id ? 'Edição' : 'Cadastro', spec.title, String(raw.nome || raw.titulo || raw.empresa || raw.email || spec.singular)), ...d.audit] }))
    announce(raw.id ? 'Alterações salvas.' : `${spec.singular[0].toUpperCase()}${spec.singular.slice(1)} cadastrada.`); setModal(null)
  }
  const deleteItem = () => {
    if (!modal?.record) return
    const id = String(modal.record.id)
    if (modal.module === 'empresas') {
      const name = String(modal.record.razaoSocial)
      setData((d) => ({ ...d, companies: d.companies.filter((x) => x.id !== id), audit: [audit('Exclusão', 'Empresas', name), ...d.audit] }))
    } else {
      const prop = ({ pendencias: 'pendencies', certificados: 'certificates', integracoes: 'integrations', grupos: 'groups', usuarios: 'users', simples: 'taxFilings', real: 'taxFilings', presumido: 'taxFilings' } as Record<string, keyof AppData>)[modal.module]
      if (prop) setData((d) => ({ ...d, [prop]: (d[prop] as Array<{ id: string }>).filter((x) => x.id !== id), audit: [audit('Exclusão', modal.module, id), ...d.audit] }))
    }
    setModal(null); announce('Registro removido da base local.')
  }
  const saveSettings = () => { localStorage.setItem('machado-settings', JSON.stringify(settings)); setData((d) => ({ ...d, audit: [audit('Atualização', 'Configurações', 'Preferências do sistema'), ...d.audit] })); announce('Preferências salvas neste navegador.') }
  const changeModule = (item: NavItem) => setSection(item.key)

  if (!ready) return <div className="loading-screen"><span className="loading-logo-frame"><img src={machadoLogo} alt="Machado Contabilidade" /></span><div className="spinner" />Carregando dados locais…</div>
  if (!logged) return <Login onLogin={() => { sessionStorage.setItem('machado-session', 'active'); setLogged(true) }} />

  const navGroups = [...new Set(nav.map((n) => n.group))]
  return <div className="app-shell">
    {mobileOpen && <button className="mobile-scrim" aria-label="Fechar navegação" onClick={() => setMobileOpen(false)} />}
    <aside className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><span className="brand-logo-frame"><img src={machadoLogo} alt="Machado Contabilidade" /></span><div className="brand-name"><strong>machado</strong><span>CONTABILIDADE</span></div><button className="sidebar-close" onClick={() => setMobileOpen(false)} aria-label="Fechar menu"><X size={17} /></button></div>
      <div className="workspace-switch"><div className="workspace-avatar">M</div><div><strong>{settings.brand || 'Machado Contabilidade'}</strong><small>Escritório contábil</small></div><ChevronDown size={15} /></div>
      <nav className="side-nav">{navGroups.map((group) => <div className="nav-group" key={group}><div className="nav-caption">{group}</div>{nav.filter((n) => n.group === group).map((item) => <button key={item.key} onClick={() => changeModule(item)} className={`nav-item ${module === item.key ? 'nav-active' : ''}`}><item.icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.key === 'pendencias' && data.pendencies.filter((p) => p.status !== 'Concluída').length > 0 && <b className="nav-count">{data.pendencies.filter((p) => p.status !== 'Concluída').length}</b>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><span className="help-icon"><CircleHelp size={17} /></span><strong>Precisa de ajuda?</strong><small>Fale com o suporte interno</small><button onClick={() => announce('Suporte: procure a equipe Machado Contabilidade.')}>Acessar suporte <ArrowUpRight size={13} /></button></div><div className="user-profile"><div className="user-avatar">OG</div><div className="user-info"><strong>Operador local</strong><small>Administrador</small></div><button onClick={() => { sessionStorage.removeItem('machado-session'); setLogged(false) }} title="Sair"><LogOut size={16} /></button></div></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><button className="menu-button" onClick={() => setMobileOpen(true)} aria-label="Abrir menu"><Menu size={21} /></button><div className="breadcrumbs"><img src={machadoLogo} alt="Machado Contabilidade" /><span>Machado Contabilidade</span><b>/</b><strong>{selected ? 'Ficha da empresa' : nav.find((n) => n.key === module)?.label}</strong></div><div className="topbar-right"><span className="local-pill"><span />Dados locais</span><button className="top-icon" onClick={() => setSection('pendencias')} title="Pendências"><Bell size={18} />{data.pendencies.some((p) => p.status !== 'Concluída') && <i />}</button><div className="top-divider" /><button className="top-user" onClick={() => setSection('usuarios')}><span className="user-avatar small">OG</span><span><b>Operador local</b><small>Administrador</small></span><ChevronDown size={14} /></button></div></header>
    <div className="page-content">
        <div className="source-note"><span className="source-dot" /><span>{DATA_SOURCE_LABEL}</span><button onClick={() => setSection('importacao')}>Carregar dados <ArrowUpRight size={13} /></button></div>
        {module === 'dashboard' && <Dashboard data={data} onNavigate={setSection} onImport={() => setSection('importacao')} />}
        {module === 'empresas' && <CompanyPage data={data} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} page={page} setPage={setPage} sort={sort} sortDir={sortDir} onSort={(key) => { setSortDir(sort === key && sortDir === 'asc' ? 'desc' : 'asc'); setSort(key) }} onAdd={() => openCompanyForm()} onEdit={openCompanyForm} onDelete={(c) => setModal({ kind: 'confirm', module, record: c as unknown as Record<string, unknown> })} onView={(c) => setSelected(c)} />}
        {['simples', 'real', 'presumido'].includes(module) && <RegimePage module={module} data={data} onAddFiling={() => setModal({ kind: 'form', module, record: { status: 'Não iniciada' } })} onAddCompany={(regime) => openCompanyForm(undefined, regime)} onView={(c) => setSelected(c)} onEditFiling={(row) => setModal({ kind: 'form', module, record: row })} onDeleteFiling={(row) => setModal({ kind: 'confirm', module, record: row })} onAdvance={(row) => { const next = row.status === 'Transmitida' ? 'Não iniciada' : row.status === 'Não iniciada' ? 'Em andamento' : 'Transmitida'; addItem(module, { ...row, status: next }) }} />}
        {selected && module === 'empresas' && <CompanyDetail company={selected} data={data} onBack={() => setSelected(null)} onEdit={() => openCompanyForm(selected)} onUpdate={(patch) => { const updated = { ...selected, ...patch, updatedAt: new Date().toISOString() }; setData((d) => ({ ...d, companies: d.companies.map((c) => c.id === selected.id ? updated : c), audit: [audit('Atualização', 'Empresas', selected.razaoSocial), ...d.audit] })); setSelected(updated) }} />}
        {specs[module] && !['simples','real','presumido'].includes(module) && <EntityPage module={module} data={data} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} page={page} setPage={setPage} sort={sort} sortDir={sortDir} onSort={(key) => { setSortDir(sort === key && sortDir === 'asc' ? 'desc' : 'asc'); setSort(key) }} onAdd={() => openNewForm(module)} onEdit={(row) => setModal({ kind: 'form', module, record: row as unknown as Record<string, unknown> })} onDelete={(row) => setModal({ kind: 'confirm', module, record: row as unknown as Record<string, unknown> })} onStatus={(row) => {
          const next = row.status === 'Concluída' ? 'Aberta' : row.status === 'Aberta' ? 'Em andamento' : 'Concluída'
          addItem(module, { ...row, status: next })
        }} />}
        {module === 'historico' && <HistoryPage audit={data.audit} query={query} setQuery={setQuery} page={page} setPage={setPage} />}
        {module === 'configuracoes' && <SettingsPage settings={settings} setSettings={setSettings} onSave={saveSettings} onClear={() => setModal({ kind: 'confirm', module: 'configuracoes', record: { id: 'clear' } })} />}
        {module === 'importacao' && <ImportPage onImport={async (file) => { setImporting(true); try { const parsed = await parseCompanies(file); setImportPreview(parsed); setModal({ kind: 'import', module: 'importacao' }) } catch (error) { announce(error instanceof Error ? error.message : 'Não foi possível ler o arquivo.', 'error') } finally { setImporting(false) } }} onExport={() => { exportCompanies(data.companies).then(() => announce('Planilha exportada.')).catch(() => announce('Não foi possível exportar a planilha.', 'error')) }} importing={importing} count={data.companies.length} />}
      </div>
    </main>
    {modal && modal.kind === 'form' && <EntityFormModal module={modal.module} record={modal.record} companies={['simples','real','presumido'].includes(modal.module) ? data.companies.filter((c) => c.regime === ({ simples:'Simples Nacional', real:'Lucro Real', presumido:'Lucro Presumido' } as Record<string,Regime>)[modal.module]) : data.companies} groups={data.groups} onSave={(v) => addItem(modal.module, v)} onClose={() => setModal(null)} />}
    {modal?.kind === 'confirm' && <Modal title={modal.module === 'configuracoes' ? 'Limpar os dados locais?' : 'Excluir este registro?'} onClose={() => setModal(null)}><p className="modal-copy">{modal.module === 'configuracoes' ? 'Esta ação remove todos os registros salvos neste navegador. Ela não altera nenhum arquivo de origem.' : `O registro “${String(modal.record?.razaoSocial || modal.record?.nome || modal.record?.titulo || 'selecionado')}” será removido da base local.`}</p><div className="modal-actions"><Button variant="outline" onClick={() => setModal(null)}>Cancelar</Button><Button variant="danger" onClick={() => { if (modal.module === 'configuracoes') { repository.clear().then(() => { setData(blankData); setModal(null); announce('Base local limpa.') }) } else deleteItem() }}>Confirmar exclusão</Button></div></Modal>}
    {modal?.kind === 'import' && importPreview && <ImportPreview preview={importPreview} onClose={() => setModal(null)} onCommit={() => { setData((d) => ({ ...d, companies: [...importPreview.companies, ...d.companies], audit: [audit('Importação local', 'Empresas', `${importPreview.companies.length} empresas`), ...d.audit] })); setModal(null); setImportPreview(null); announce(`${importPreview.companies.length} empresas adicionadas à base local.`) }} />}
    {toast && <Toast message={toast} kind={toastKind} onClose={() => setToast('')} />}
  </div>
}

function Login({ onLogin }: { onLogin: () => void }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('')
  return <div className="login-page"><div className="login-left"><div className="login-brand"><span className="login-logo-frame"><img src={machadoLogo} alt="Machado Contabilidade" /></span></div><div className="login-message"><span className="eyebrow">CONTROLE FISCAL</span><h1>Gestão contábil,<br /><em>do seu jeito.</em></h1><p>Uma visão integrada das empresas, obrigações e rotinas do seu escritório.</p><div className="login-art"><div className="art-card art-one"><span><Building2 size={18} /></span><div><strong>Carteira organizada</strong><small>Empresas e regimes em um só lugar</small></div></div><div className="art-card art-two"><span><ClipboardCheck size={18} /></span><div><strong>Rotina sob controle</strong><small>Pendências acompanhadas de perto</small></div></div><div className="art-orbit" /></div></div><small className="login-copy">© 2026 Machado Contabilidade</small></div><div className="login-right"><form className="login-card" onSubmit={(e) => { e.preventDefault(); if (!email || password.length < 4) { setError('Informe seu e-mail e uma senha com pelo menos 4 caracteres.'); return } onLogin() }}><div className="login-welcome"><div className="mobile-brand"><img src={machadoLogo} alt="Machado Contabilidade" /></div><h2>Bem-vindo de volta</h2><p>Acesse sua área de controle fiscal.</p></div><label className="field"><span>E-mail</span><input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="seu@email.com" /></label><label className="field"><span>Senha</span><input type="password" required minLength={4} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Digite sua senha" /></label><div className="login-options"><label><input type="checkbox" /> Manter conectado</label><button type="button" onClick={() => setError('Esta tela usa autenticação local de demonstração. Conecte o provedor de identidade na etapa de produção.')}>Esqueci minha senha</button></div>{error && <div className="form-error"><AlertTriangle size={15} />{error}</div>}<Button type="submit" className="login-submit">Entrar <ArrowUpRight size={15} /></Button><div className="login-demo"><span>ACESSO LOCAL</span><p>Esta tela não autentica contra servidor. Use qualquer e-mail e senha com 4 ou mais caracteres.</p></div></form><div className="login-footer"><ShieldCheck size={14} /> Sessão demonstrativa armazenada neste navegador</div></div></div>
}

function Dashboard({ data, onNavigate, onImport }: { data: AppData; onNavigate: (key: ModuleKey) => void; onImport: () => void }) {
  const active = data.companies.filter((c) => c.status === 'Ativa').length; const inactive = data.companies.filter((c) => c.status === 'Inativa').length; const suspended = data.companies.filter((c) => c.status === 'Suspensa').length; const open = data.pendencies.filter((p) => p.status !== 'Concluída').length
  const regimes = ['Simples Nacional', 'Lucro Real', 'Lucro Presumido'] as const
  const certificates = data.certificates.filter((certificate) => certificate.sourceSheet === 'RCD')
  const overdue = certificates.filter((certificate) => certificate.status === 'Expirado').length; const due = certificates.filter((certificate) => certificate.status === 'Vence em breve').length; const regular = certificates.filter((certificate) => certificate.status === 'Válido').length
  const connectedIntegrations = data.integrations.filter((item) => item.status === 'Conectada').length; const attentionIntegrations = data.integrations.filter((item) => item.status === 'Atenção' || item.status === 'Desconectada').length; const unstatedIntegrations = data.integrations.filter((item) => item.status === 'Sem status').length
  const analystCounts = data.pendencies.filter((item) => item.status !== 'Concluída').reduce<Record<string, number>>((counts, item) => ({ ...counts, [item.responsavel || 'Sem responsável']: (counts[item.responsavel || 'Sem responsável'] ?? 0) + 1 }), {})
  return <><PageTitle eyebrow={new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date()).toLocaleUpperCase('pt-BR')} title="Bom dia, equipe Machado" subtitle="Aqui está um resumo da operação do seu escritório." action={<Button onClick={onImport}><FileSpreadsheet size={16} /> Importar planilha</Button>} />
    <div className="welcome-banner"><div className="welcome-symbol"><Building2 size={20} /></div><div><strong>Carteira fiscal Machado</strong><p>367 registros da planilha de novembro de 2026; os indicadores abaixo usam os dados de origem.</p></div><button onClick={onImport}>Importar outra planilha <ArrowUpRight size={14} /></button></div>
    <div className="metric-grid"><Metric title="Empresas na carteira" value={data.companies.length.toString()} note="Registros disponíveis" icon={Building2} tone="green" onClick={() => onNavigate('empresas')} /><Metric title="Empresas ativas" value={active.toString()} note="Situação de origem" icon={Check} tone="blue" onClick={() => onNavigate('empresas')} /><Metric title="Pendências abertas" value={open.toString()} note="Lançadas na central" icon={AlertTriangle} tone="amber" onClick={() => onNavigate('pendencias')} /><Metric title="Certificados em listas RCD" value={certificates.length.toString()} note={`${overdue} vencidos · ${due} a vencer · ${regular} regulares`} icon={KeyRound} tone="purple" onClick={() => onNavigate('certificados')} /></div>
    <div className="dashboard-grid"><section className="panel regime-panel"><div className="panel-heading"><div><h2>Empresas por regime</h2><p>Distribuição da carteira fiscal · dados de origem</p></div><button onClick={() => onNavigate('empresas')}>Ver empresas <ArrowUpRight size={13} /></button></div><div className="regime-content"><div className="donut" style={{ '--pct': data.companies.length ? `${data.companies.filter((c) => c.regime === regimes[0]).length / data.companies.length * 100}%` : '0%' } as React.CSSProperties}><div><strong>{data.companies.length}</strong><small>empresas</small></div></div><div className="legend-list">{regimes.map((r, i) => <button key={r} onClick={() => onNavigate(i === 0 ? 'simples' : i === 1 ? 'real' : 'presumido')}><span className={`legend-dot legend-${i}`} /><span>{r}</span><b>{data.companies.filter((c) => c.regime === r).length}</b></button>)}</div></div></section><section className="panel deadlines-panel"><div className="panel-heading"><div><h2>Situação das empresas</h2><p>Aba SN, LR e LP - 112026</p></div><button onClick={() => onNavigate('empresas')}>Ver carteira <ArrowUpRight size={13} /></button></div><div className="source-status-list">{[['Ativas',active,'status-active'],['Desativadas',inactive,'status-inactive'],['Suspensas',suspended,'status-suspended']].map(([label,value,tone])=><div className="source-status-row" key={String(label)}><span className={`status-mark ${tone}`} /><span>{label}</span><b>{value}</b><div><i style={{width:`${data.companies.length ? Number(value)/data.companies.length*100 : 0}%`}} /></div></div>)}</div><p className="data-asof">367 CNPJs distintos · nenhuma duplicidade removida</p></section></div>
    <div className="dashboard-grid dashboard-grid-lower"><section className="panel deadlines-panel"><div className="panel-heading"><div><h2>Certificados UNECONT</h2><p>Listas em 26/10/2026 · validades atuais</p></div><button onClick={() => onNavigate('certificados')}>Abrir controle <ArrowUpRight size={13} /></button></div>{certificates.length ? <div className="source-status-list"><div className="source-status-row"><span className="status-mark status-inactive" /><span>Expirados</span><b>{overdue}</b></div><div className="source-status-row"><span className="status-mark status-suspended" /><span>A vencer</span><b>{due}</b></div><div className="source-status-row"><span className="status-mark status-active" /><span>Regulares</span><b>{regular}</b></div></div> : <div className="compact-empty">Sem linhas RCD vinculadas a esta carteira.</div>}</section><section className="panel deadlines-panel"><div className="panel-heading"><div><h2>Integrações</h2><p>Status ZEN Qdrive / UNECONT na origem</p></div><button onClick={() => onNavigate('integracoes')}>Ver integrações <ArrowUpRight size={13} /></button></div><div className="source-status-list"><div className="source-status-row"><span className="status-mark status-active" /><span>Conectadas · ZEN Qdrive / UNECONT</span><b>{connectedIntegrations}</b></div><div className="source-status-row"><span className="status-mark status-inactive" /><span>Com atenção</span><b>{attentionIntegrations}</b></div><div className="source-status-row"><span className="status-mark status-suspended" /><span>Sem status informado</span><b>{unstatedIntegrations}</b></div></div><p className="data-asof">Vazio ou “-” não é considerado concluído.</p></section><section className="panel deadlines-panel"><div className="panel-heading"><div><h2>Pendências por responsável</h2><p>Registros da central de pendências</p></div><button onClick={() => onNavigate('pendencias')}>Ver pendências <ArrowUpRight size={13} /></button></div>{Object.entries(analystCounts).length ? <div className="source-status-list">{Object.entries(analystCounts).map(([name,count])=><div className="source-status-row" key={name}><span className="status-mark status-suspended" /><span>{name}</span><b>{count}</b></div>)}</div> : <div className="compact-empty">Nenhuma pendência cadastrada. A planilha não atribui pendências por responsável.</div>}</section></div>
    <section className="panel recent-panel"><div className="panel-heading"><div><h2>Atividade recente</h2><p>Últimas atualizações no sistema</p></div><button onClick={() => onNavigate('historico')}>Ver histórico <ArrowUpRight size={13} /></button></div>{data.audit.length ? data.audit.slice(0,5).map((a) => <div className="activity-row" key={a.id}><span className="activity-icon"><Activity size={15} /></span><div><strong>{a.acao} · {a.modulo}</strong><small>{a.detalhe}</small></div><time>{new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(a.data))}</time></div>) : <div className="activity-empty"><Clock3 size={18} /><span>As alterações feitas neste espaço aparecerão aqui.</span></div>}</section>
  </>
}
function Metric({ title, value, note, icon: Icon, tone, onClick }: { title: string; value: string; note: string; icon: LucideIcon; tone: string; onClick: () => void }) {
  return <button className="metric-card" onClick={onClick}><div className="metric-top"><span>{title}</span><span className={`metric-icon metric-${tone}`}><Icon size={17} /></span></div><div className="metric-value">{value}</div><div className="metric-note">{note}<span className="metric-trend"><ArrowUpRight size={13} /></span></div></button>
}

function CompanyPage({ data, query, setQuery, filter, setFilter, page, setPage, sort, sortDir, onSort, onAdd, onEdit, onDelete, onView }: { data: AppData; query: string; setQuery: (v:string)=>void; filter: string; setFilter:(v:string)=>void; page:number; setPage:(v:number)=>void; sort:string; sortDir:'asc'|'desc'; onSort:(v:string)=>void; onAdd:()=>void; onEdit:(c:Company)=>void; onDelete:(c:Company)=>void; onView:(c:Company)=>void }) {
  const rows = useMemo(() => filterRows(data.companies, query, filter, 'status', sort, sortDir), [data.companies, query, filter, sort, sortDir])
  const columns: Column<Company>[] = [{ key: 'razaoSocial', label: 'Empresa', render: (c) => <button className="company-cell" onClick={() => onView(c)}><span className="company-avatar">{initials(c.nomeFantasia || c.razaoSocial)}</span><span><b>{c.razaoSocial}</b><small>{c.nomeFantasia || c.unidade || '—'}</small></span></button> }, { key: 'cnpj', label: 'CNPJ', render: (c) => <span className="mono">{formatCnpj(c.cnpj)}</span> }, { key: 'regime', label: 'Regime', render: (c) => <span className="regime-tag">{c.regime}</span> }, { key: 'responsavel', label: 'Responsável', render: (c) => c.responsavel || '—' }, { key: 'status', label: 'Situação', render: (c) => <StatusBadge>{c.status}</StatusBadge> }]
  return <><PageTitle eyebrow="CARTEIRA DE CLIENTES" title="Empresas" subtitle="Consulte e organize os cadastros oficiais e os dados locais do escritório." action={<><Button variant="outline" onClick={() => { exportCompanies(data.companies).then(()=>{}).catch(()=>{}) }}><span className="hide-small">Exportar</span><FileSpreadsheet size={15} /></Button><Button onClick={onAdd}><span className="btn-plus">+</span> Nova empresa</Button></>} /><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Buscar empresa, CNPJ, responsável ou dados de origem" /><FilterSelect value={filter} onChange={setFilter} options={['Ativa','Inativa','Suspensa','Em implantação']} label="situação" /><span className="toolbar-count">{rows.length} empresa{rows.length===1?'':'s'}</span></div><section className="panel table-panel"><DataTable rows={rows} columns={columns} page={page} pageSize={10} onPage={setPage} onSort={onSort} sortKey={sort} sortDir={sortDir} onEdit={onEdit} onDelete={onDelete} onView={onView} empty="Nenhuma empresa cadastrada" emptyDetail="Importe a planilha real de novembro/2026 ou cadastre uma empresa para começar." /></section></>
}
function filterRows<T extends Record<string, unknown>>(items: T[], query: string, filter: string, filterKey: string, sort: string, dir: 'asc'|'desc') {
  let out = items.filter((row) => (!filter || row[filterKey] === filter) && (!query || JSON.stringify(row).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))))
  if (sort) out = [...out].sort((a,b) => String(a[sort] ?? '').localeCompare(String(b[sort] ?? ''), 'pt-BR') * (dir === 'asc' ? 1 : -1))
  return out
}
function RegimePage({ module, data, onAddFiling, onAddCompany, onView, onEditFiling, onDeleteFiling, onAdvance }: { module: ModuleKey; data: AppData; onAddFiling:()=>void; onAddCompany:(r:Regime)=>void; onView:(c:Company)=>void; onEditFiling:(row:TaxFiling)=>void; onDeleteFiling:(row:TaxFiling)=>void; onAdvance:(row:TaxFiling)=>void }) {
  const regime: Regime = module === 'simples' ? 'Simples Nacional' : module === 'real' ? 'Lucro Real' : 'Lucro Presumido'; const companies = data.companies.filter((c) => c.regime === regime); const [query, setQuery] = useState(''); const [page, setPage] = useState(1)
  const filings = data.taxFilings.filter((f) => f.regime === regime && (!query || Object.values(f).some((v) => String(v ?? '').toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')))))
  const companyColumns: Column<Company>[] = [{key:'razaoSocial',label:'Empresa',render:(c)=><button className="company-cell" onClick={()=>onView(c)}><span className="company-avatar">{initials(c.razaoSocial)}</span><span><b>{c.razaoSocial}</b><small>{c.nomeFantasia || '—'}</small></span></button>},{key:'cnpj',label:'CNPJ',render:(c)=><span className="mono">{formatCnpj(c.cnpj)}</span>},{key:'responsavel',label:'Responsável',render:(c)=>c.responsavel||'—'},{key:'status',label:'Situação',render:(c)=><StatusBadge>{c.status}</StatusBadge>}]
  const filingColumns: Column<TaxFiling>[] = [{key:'empresa',label:'Empresa'},{key:'periodo',label:'Competência'},{key:'obrigacao',label:'Rotina / obrigação'},{key:'responsavel',label:'Responsável',render:(f)=>f.responsavel||'—'},{key:'prazo',label:'Prazo',render:(f)=>formatDate(f.prazo)},{key:'status',label:'Status',render:(f)=><StatusBadge>{f.status}</StatusBadge>}]
  return <><PageTitle eyebrow="APURAÇÃO FISCAL" title={regime} subtitle="Acompanhe empresas e fechamentos por competência." action={<><Button variant="outline" onClick={()=>onAddCompany(regime)}><span className="btn-plus">+</span> Empresa</Button><Button disabled={!companies.length} onClick={onAddFiling}><span className="btn-plus">+</span> Novo fechamento</Button></>} /><div className="metric-grid regime-metrics"><Metric title="Empresas enquadradas" value={String(companies.length)} note="Carteira do regime" icon={Building2} tone="green" onClick={()=>document.getElementById('regime-companies')?.scrollIntoView({behavior:'smooth'})}/><Metric title="Fechamentos registrados" value={String(data.taxFilings.filter((f)=>f.regime===regime).length)} note="Competências cadastradas" icon={ClipboardCheck} tone="blue" onClick={()=>document.getElementById('regime-filings')?.scrollIntoView({behavior:'smooth'})}/><Metric title="Em andamento" value={String(data.taxFilings.filter((f)=>f.regime===regime&&f.status==='Em andamento').length)} note="Acompanhamento manual" icon={Clock3} tone="amber" onClick={()=>document.getElementById('regime-filings')?.scrollIntoView({behavior:'smooth'})}/><Metric title="Transmitidas" value={String(data.taxFilings.filter((f)=>f.regime===regime&&f.status==='Transmitida').length)} note="Registros concluídos" icon={Check} tone="purple" onClick={()=>document.getElementById('regime-filings')?.scrollIntoView({behavior:'smooth'})}/></div><section id="regime-companies" className="panel regime-table-panel"><div className="panel-heading"><div><h2>Empresas neste regime</h2><p>Cadastro central da carteira Machado</p></div></div><DataTable rows={companies} columns={companyColumns} page={1} pageSize={10} onPage={()=>{}} onSort={()=>{}} onView={onView} empty="Nenhuma empresa neste regime" emptyDetail="Cadastre uma empresa e selecione este regime tributário." /></section><section id="regime-filings" className="panel regime-table-panel"><div className="panel-heading"><div><h2>Fechamentos e obrigações</h2><p>Rotinas cadastradas por competência. Nenhum período é presumido.</p></div><Button variant="outline" disabled={!companies.length} onClick={onAddFiling}><span className="btn-plus">+</span> Novo fechamento</Button></div><div className="toolbar regime-search"><SearchBox value={query} onChange={(v)=>{setQuery(v);setPage(1)}} placeholder="Buscar empresa, competência ou obrigação"/><span className="toolbar-count">{filings.length} registro{filings.length===1?'':'s'}</span></div><DataTable rows={filings} columns={filingColumns} page={page} pageSize={10} onPage={setPage} onSort={()=>{}} onEdit={onEditFiling} onDelete={onDeleteFiling} onView={onAdvance} viewLabel="Avançar status" empty="Nenhum fechamento registrado" emptyDetail={companies.length ? 'Cadastre as rotinas e competências que o escritório acompanha.' : 'Adicione uma empresa neste regime antes de cadastrar fechamentos.'} /></section></>
}

function CompanyDetail({ company, data, onBack, onEdit, onUpdate }: { company: Company; data: AppData; onBack:()=>void; onEdit:()=>void; onUpdate:(patch:Partial<Company>)=>void }) {
  const pending = data.pendencies.filter((p) => p.empresa === company.razaoSocial); const certs = data.certificates.filter((c) => c.empresa === company.razaoSocial || c.cnpj && normalizeCnpj(c.cnpj) === normalizeCnpj(company.cnpj))
  const sourceRecords = company.sourceRecords ?? []
  return <div className="detail-view"><button className="back-link" onClick={onBack}>‹ Voltar para empresas</button><div className="detail-hero"><div className="detail-avatar">{initials(company.nomeFantasia||company.razaoSocial)}</div><div className="detail-title"><span className="eyebrow">FICHA DA EMPRESA</span><h1>{company.razaoSocial}</h1><p>{company.unidade || company.nomeFantasia || 'Dados cadastrais'} <span>·</span> <span className="mono">{formatCnpj(company.cnpj)}</span></p></div><div className="detail-actions"><StatusBadge>{company.status}</StatusBadge><Button variant="outline" onClick={onEdit}>Editar cadastro</Button></div></div><div className="detail-tabs"><span className="tab-active">Visão geral</span><button onClick={()=>document.getElementById('company-activity')?.scrollIntoView({behavior:'smooth'})}>Atividade</button><button onClick={()=>document.getElementById('company-source')?.scrollIntoView({behavior:'smooth'})}>Dados de origem</button></div><div className="detail-grid"><section className="panel detail-panel"><div className="panel-heading"><div><h2>Dados cadastrais</h2><p>Informações da planilha oficial e dados locais</p></div><button onClick={onEdit}>Editar <PencilIcon/></button></div><div className="detail-fields">{[['CNPJ',formatCnpj(company.cnpj)],['Regime tributário',company.regime],['Situação',company.status],['Matriz / filial',company.unidade],['Responsável interno',company.responsavel],['Localidade',[company.cidade,company.uf].filter(Boolean).join(' / ')],['Grupo',company.grupo],['Observações',company.observacoes],['E-mail',company.email],['Telefone',company.telefone]].map(([k,v])=><div key={k}><small>{k}</small><strong>{v||'—'}</strong></div>)}</div></section><div className="detail-side"><section className="panel compact-panel"><div className="panel-heading"><div><h2>Pendências</h2><p>Vinculadas à empresa</p></div><span className="mini-count">{pending.length}</span></div>{pending.length ? pending.slice(0,4).map((p)=><div className="compact-row" key={p.id}><span className="deadline-bullet"/><div><b>{p.titulo}</b><small>{formatDate(p.prazo)} · {p.status}</small></div></div>):<div className="compact-empty">Nenhuma pendência vinculada.</div>}</section><section className="panel compact-panel"><div className="panel-heading"><div><h2>Certificados</h2><p>Validade e controle</p></div><span className="mini-count">{certs.length}</span></div>{certs.length ? certs.map((c)=><div className="compact-row" key={c.id}><KeyRound size={16}/><div><b>{c.tipo}</b><small>Validade {formatDate(c.validade)}</small></div><StatusBadge>{c.status}</StatusBadge></div>):<div className="compact-empty">Nenhum certificado vinculado.</div>}</section></div></div><section id="company-activity" className="panel company-activity"><h2>Controle fiscal</h2><p>As rotinas por regime são organizadas nos módulos do menu lateral.</p><div className="inline-actions"><button onClick={()=>onUpdate({status:company.status==='Ativa'?'Inativa':'Ativa'})}>Alternar situação cadastral</button><button onClick={onEdit}>Editar vínculo de grupo</button></div></section><section id="company-source" className="panel source-records-panel"><div className="panel-heading"><div><h2>Dados de origem</h2><p>{sourceRecords.length} linha(s) vinculada(s) pelo CNPJ. Valores mantidos como no arquivo.</p></div></div>{sourceRecords.map((record,index)=><article className="source-record" key={record.sheet+'-'+record.rowNumber+'-'+index}><div className="source-record-heading"><strong>{record.sheet}{record.section ? ' · ' + record.section : ''}</strong><small>Linha {record.rowNumber}</small></div><div className="source-record-fields">{Object.entries(record.values).filter(([label,value])=>label && String(value).trim()).map(([label,value])=><div key={label}><small>{label}</small><strong>{value}</strong></div>)}</div></article>)}</section></div>
}
function PencilIcon(){return <span aria-hidden="true">↗</span>}

function EntityPage({ module, data, query, setQuery, filter, setFilter, page, setPage, sort, sortDir, onSort, onAdd, onEdit, onDelete, onStatus }: { module:ModuleKey; data:AppData; query:string; setQuery:(v:string)=>void; filter:string; setFilter:(v:string)=>void; page:number; setPage:(v:number)=>void; sort:string; sortDir:'asc'|'desc'; onSort:(v:string)=>void; onAdd:()=>void; onEdit:(row:Record<string,unknown>)=>void; onDelete:(row:Record<string,unknown>)=>void; onStatus:(row:Record<string,unknown>)=>void }) {
  const spec=specs[module]!; const prop=({pendencias:'pendencies',certificados:'certificates',integracoes:'integrations',grupos:'groups',usuarios:'users'} as const)[module as 'pendencias'];
  const original=(data[prop] as unknown as Array<Record<string,unknown>>); const statusKey = module==='pendencias'||module==='certificados'||module==='integracoes'||module==='usuarios' ? 'status' : ''
  const rows=useMemo(()=>filterRows(original,query,filter,statusKey,sort,sortDir),[original,query,filter,sort,sortDir,statusKey])
  const keyFields=module==='pendencias'?['titulo','empresa','tipo','prioridade','prazo','status']:module==='certificados'?['empresa','tipo','validade','responsavel','status']:module==='integracoes'?['nome','fornecedor','status','ultimaSincronia']:module==='grupos'?['nome','descricao','dataImportacao','dataApuracao']:['nome','email','perfil','status']
  const labels:Record<string,string>={titulo:'Descrição',empresa:'Empresa',tipo:'Tipo',prioridade:'Prioridade',prazo:'Prazo',status:'Status',validade:'Validade',responsavel:'Responsável',nome:'Nome',fornecedor:'Fornecedor',ultimaSincronia:'Última sincronia',descricao:'Categoria',dataImportacao:'Data de importação',dataApuracao:'Data da apuração',email:'E-mail',perfil:'Perfil'}
  const columns:Column<Record<string,unknown>>[]=keyFields.map((key)=>({key,label:labels[key]??key,render:(r)=>key==='status'||key==='prioridade'?<StatusBadge>{String(r[key]??'—')}</StatusBadge>:key==='prazo'||key==='validade'||key==='ultimaSincronia'?formatDate(String(r[key]??'')):String(r[key]??'—')}))
  return <><PageTitle eyebrow="GESTÃO OPERACIONAL" title={spec.title} subtitle={module==='pendencias'?'Organize prioridades, responsáveis e prazos.':'Consulte e mantenha os registros atualizados.'} action={<Button onClick={onAdd}><span className="btn-plus">+</span> Novo registro</Button>} /><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder={`Buscar em ${spec.title.toLocaleLowerCase('pt-BR')}`} />{statusKey&&<FilterSelect value={filter} onChange={setFilter} options={[...new Set(original.map((r)=>String(r.status??'')))].filter(Boolean)} label="status" />}<span className="toolbar-count">{rows.length} registro{rows.length===1?'':'s'}</span></div><section className="panel table-panel"><DataTable rows={rows as Array<Record<string,unknown>&{id:string}>} columns={columns} page={page} pageSize={10} onPage={setPage} onSort={onSort} sortKey={sort} sortDir={sortDir} onEdit={onEdit} onDelete={onDelete} onView={module==='pendencias'?onStatus:undefined} viewLabel="Avançar status" empty={`Nenhum registro em ${spec.title.toLocaleLowerCase('pt-BR')}`} emptyDetail="Adicione o primeiro registro ou importe os dados de origem quando disponíveis." /></section></>
}

function EntityFormModal({ module, record, companies, groups, onSave, onClose }: { module:ModuleKey; record?:Record<string,unknown>; companies:Company[]; groups:Group[]; onSave:(v:Record<string,unknown>)=>void; onClose:()=>void }) {
  const company=module==='empresas'; const fields=company?fieldsCompany:specs[module]?.fields??[]; const [values,setValues]=useState<Record<string,string>>(()=>Object.fromEntries(fields.map((f)=>[f.key,String(record?.[f.key]??'')]))); const [errors,setErrors]=useState<Record<string,string>>({});
  const [permissions,setPermissions]=useState<string[]>(()=>Array.isArray(record?.permissoes)?record.permissoes.map(String):roleDefaults[String(record?.perfil??'')]??[])
  const title=record?.id?`Editar ${company?'empresa':specs[module]?.singular}`:`Nova ${company?'empresa':specs[module]?.singular}`
  const update=(key:string,value:string)=>{setValues((v)=>({...v,[key]:value}));setErrors((e)=>({...e,[key]:''}))}
  const submit=(event:React.FormEvent)=>{event.preventDefault(); if(company){const result=validateCompany(values);if(!result.success){setErrors(result.errors);return}}else{const invalid=Object.fromEntries(fields.filter((f)=>f.required&&!values[f.key]?.trim()).map((f)=>[f.key,`${f.label} é obrigatório.`]));if(Object.keys(invalid).length){setErrors(invalid);return}if(module==='usuarios'&&values.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)){setErrors({email:'Informe um e-mail válido.'});return}}
    if(company&&dataDuplicateCnpj(values.cnpj,companies,String(record?.id??''))){setErrors({cnpj:'Este CNPJ já está cadastrado.'});return}
    onSave({...record,...values,...(module==='usuarios'?{permissoes:permissions}:{})})
  }
  return <Modal title={title} onClose={onClose} size="wide"><form onSubmit={submit} noValidate><div className="form-grid">{fields.map((f)=>{const options=f.options??(f.key==='grupo'?groups.map((g)=>g.nome):[]);return <label key={f.key} className={`field ${f.wide?'field-wide':''}`}><span>{f.label}{f.required&&<i> *</i>}</span>{options.length?<select value={values[f.key]??''} onChange={(e)=>{update(f.key,e.target.value);if(module==='usuarios'&&f.key==='perfil')setPermissions(roleDefaults[e.target.value]??[])}}><option value="">Selecione</option>{options.map((o)=><option key={o}>{o}</option>)}</select>:f.key==='empresa'&&companies.length>0?<select value={values[f.key]??''} onChange={(e)=>update(f.key,e.target.value)}><option value="">Selecione a empresa</option>{companies.map((c)=><option key={c.id}>{c.razaoSocial}</option>)}</select>:f.key==='observacoes'||f.key==='descricao'?<textarea rows={3} value={values[f.key]??''} onChange={(e)=>update(f.key,e.target.value)} />:<input type={f.type??'text'} value={values[f.key]??''} maxLength={f.key==='uf'?2:undefined} onChange={(e)=>update(f.key,e.target.value)} />}<small className="field-error">{errors[f.key]}</small></label>})}</div>{module==='usuarios'&&<fieldset className="permission-box"><legend>Acessos permitidos neste perfil</legend><div className="permission-grid">{permissionAreas.map((area)=><label key={area}><input type="checkbox" checked={permissions.includes(area)} onChange={(e)=>setPermissions((current)=>e.target.checked?[...current,area]:current.filter((x)=>x!==area))}/><span>{permissionLabels[area]}</span></label>)}</div><small>Estes acessos ficam registrados junto ao perfil. A aplicação real dos bloqueios exige autenticação de servidor, planejada para a fase de produção.</small></fieldset>}<div className="modal-actions"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit">Salvar cadastro</Button></div></form></Modal>
}
function dataDuplicateCnpj(value:string,companies:Company[],except:string){const digits=normalizeCnpj(value);return companies.some((c)=>c.id!==except&&normalizeCnpj(c.cnpj)===digits)}

function HistoryPage({ audit, query, setQuery, page, setPage }: { audit:AuditEntry[]; query:string; setQuery:(v:string)=>void; page:number; setPage:(p:number)=>void }) {
  const rows=useMemo(()=>filterRows(audit as unknown as Array<Record<string,unknown>>,query,'','', 'data','desc'),[audit,query]);const columns:Column<AuditEntry>[]=[{key:'data',label:'Data e hora',render:(a)=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(a.data))},{key:'usuario',label:'Usuário'},{key:'acao',label:'Ação',render:(a)=><StatusBadge>{a.acao}</StatusBadge>},{key:'modulo',label:'Módulo'},{key:'detalhe',label:'Detalhes'}]
  return <><PageTitle eyebrow="GOVERNANÇA" title="Histórico de alterações" subtitle="Trilha de auditoria dos dados mantidos neste navegador." /><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Buscar por usuário, módulo ou ação" /><span className="toolbar-count">{rows.length} evento{rows.length===1?'':'s'}</span></div><section className="panel table-panel"><DataTable rows={rows as unknown as AuditEntry[]} columns={columns} page={page} pageSize={12} onPage={setPage} onSort={()=>{}} empty="Sem atividade registrada" emptyDetail="Alterações de cadastros aparecerão nesta trilha." /></section></>
}

function SettingsPage({ settings, setSettings, onSave, onClear }: { settings:Record<string,any>; setSettings:(v:Record<string,any>)=>void; onSave:()=>void; onClear:()=>void }) {
  return <><PageTitle eyebrow="PREFERÊNCIAS" title="Configurações do sistema" subtitle="Personalize a experiência deste espaço local." action={<Button onClick={onSave}>Salvar preferências</Button>} /><div className="settings-layout"><section className="panel settings-panel"><div className="settings-section-head"><span className="settings-icon"><Settings size={17}/></span><div><h2>Identidade do escritório</h2><p>Informações exibidas na navegação.</p></div></div><label className="field"><span>Nome do escritório</span><input value={settings.brand} onChange={(e)=>setSettings({...settings,brand:e.target.value})}/></label><div className="settings-note"><span className="settings-logo-frame"><img src={machadoLogo} alt="Machado Contabilidade" /></span><div><strong>Machado Contabilidade</strong><small>Logo oficial aplicada; a apresentação em fundo claro mantém as cores originais.</small></div></div></section><section className="panel settings-panel"><div className="settings-section-head"><span className="settings-icon"><Bell size={17}/></span><div><h2>Notificações</h2><p>Preferências para alertas no ambiente local.</p></div></div><label className="toggle-row"><span><strong>Alertas de vencimento</strong><small>Exibir alertas para prazos e pendências.</small></span><input type="checkbox" checked={settings.notifications} onChange={(e)=>setSettings({...settings,notifications:e.target.checked})}/></label><div className="field"><span>Início da semana</span><select value={settings.weekStart} onChange={(e)=>setSettings({...settings,weekStart:e.target.value})}><option value="monday">Segunda-feira</option><option value="sunday">Domingo</option></select></div></section><section className="panel settings-panel danger-zone"><div className="settings-section-head"><span className="settings-icon red"><AlertTriangle size={17}/></span><div><h2>Dados locais</h2><p>Registros salvos apenas no navegador atual.</p></div></div><p>Os dados de origem importados não são modificados. A limpeza remove apenas a cópia de trabalho local.</p><Button variant="danger" onClick={onClear}>Limpar base local</Button></section></div></>
}

function ImportPage({ onImport, onExport, importing, count }: { onImport:(f:File)=>void; onExport:()=>void; importing:boolean; count:number }) {
  return <><PageTitle eyebrow="DADOS E PLANILHAS" title="Importar e exportar" subtitle="Carregue empresas para a base local ou baixe uma cópia dos registros atuais." /><div className="import-grid"><section className="panel import-panel"><div className="import-step"><span>01</span><div><h2>Importar empresas</h2><p>Selecione a planilha de novembro/2026. Os dados serão validados e exibidos para revisão antes de entrar na base local deste navegador.</p></div></div><FilePicker onFile={onImport}/>{importing&&<div className="processing"><span className="spinner small-spinner"/>Lendo e validando a planilha…</div>}<div className="import-hint"><AlertTriangle size={15}/><span>Requer colunas de Razão Social e CNPJ. O arquivo original permanece inalterado; a importação é somente para a base local de trabalho.</span></div></section><section className="panel import-panel"><div className="import-step"><span>02</span><div><h2>Exportar dados</h2><p>Baixe a carteira cadastrada em formato Excel para conferência ou continuidade do trabalho.</p></div></div><div className="export-box"><span className="excel-icon"><FileSpreadsheet size={22}/></span><div><strong>Empresas Machado</strong><small>{count} cadastro{count===1?'':'s'} · formato .xlsx</small></div><Button variant="outline" onClick={onExport}><ArrowDownRight size={15}/> Exportar</Button></div><div className="import-hint"><ShieldCheck size={15}/><span>Exportar gera uma cópia. Não modifica a fonte nem a base local.</span></div></section></div><section className="panel import-mapping"><div><h2>Formato esperado</h2><p>Os nomes das colunas aceitam variações comuns em português.</p></div><div className="mapping-tags">{['Razão Social *','CNPJ *','Nome Fantasia','Regime','Status','Cidade','UF','Responsável','E-mail','Telefone','Grupo'].map((x)=><span key={x}>{x}</span>)}</div></section></>
}

function ImportPreview({ preview, onClose, onCommit }: { preview:{companies:Company[];errors:string[]}; onClose:()=>void; onCommit:()=>void }) {
  const [confirm,setConfirm]=useState(false);const columns:Column<Company>[]=[{key:'razaoSocial',label:'Razão social'},{key:'cnpj',label:'CNPJ',render:(c)=>formatCnpj(c.cnpj)},{key:'regime',label:'Regime'},{key:'status',label:'Situação'}]
  return <Modal title="Revisar importação" onClose={onClose} size="wide"><div className="preview-summary"><span className="preview-good"><Check size={16}/> {preview.companies.length} empresa{preview.companies.length===1?'':'s'} válida{preview.companies.length===1?'':'s'}</span>{preview.errors.length>0&&<span className="preview-error"><AlertTriangle size={16}/> {preview.errors.length} linha{preview.errors.length===1?'':'s'} ignorada{preview.errors.length===1?'':'s'}</span>}</div>{preview.companies.length>0?<div className="preview-table"><DataTable rows={preview.companies} columns={columns} page={1} pageSize={5} onPage={()=>{}} onSort={()=>{}} empty="Sem registros" emptyDetail="" />{preview.companies.length>5&&<div className="preview-overflow">Prévia das primeiras 5 linhas de {preview.companies.length}.</div>}</div>:<EmptyState title="Nenhuma linha válida encontrada" detail="Confira se a planilha contém as colunas de Razão Social e CNPJ."/>}{preview.errors.length>0&&<details className="import-errors"><summary>Ver erros de validação</summary><ul>{preview.errors.slice(0,20).map((e,i)=><li key={i}>{e}</li>)}</ul></details>}{!confirm?<div className="modal-actions"><Button variant="outline" onClick={onClose}>Voltar</Button><Button disabled={!preview.companies.length} onClick={()=>setConfirm(true)}>Adicionar à base local</Button></div>:<div className="confirm-local"><span><AlertTriangle size={17}/> Essa etapa apenas atualiza os dados de trabalho deste navegador. Nenhum banco externo será acessado.</span><div className="modal-actions"><Button variant="outline" onClick={()=>setConfirm(false)}>Revisar novamente</Button><Button onClick={onCommit}>Confirmar importação local</Button></div></div>}</Modal>
}
